package com.simibubi.create.test;
import com.simibubi.create.*;
import com.simibubi.create.content.decoration.palettes.*;
import com.simibubi.create.foundation.block.CopperBlockSet;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.core.registries.*;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.resources.ResourceKey;
import net.minecraft.tags.FluidTags;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.item.crafting.*;
import net.minecraft.world.item.enchantment.Enchantments;
import net.minecraft.world.level.ItemLike;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.WeatheringCopper.WeatherState;
import net.minecraft.world.level.block.state.properties.*;
import net.minecraft.world.phys.*;
/** Proposed native cases only. Runtime and natural random-tick aging UNRUN. */
public final class WindowsCopperGameTests {
 private static final String STRUCTURE="create_test:reservoir";private static final BlockPos P=new BlockPos(8,8,8);
 @GameTest(structure=STRUCTURE)public void real35NewWindowsAnd48CopperOwnersPreserveOriginalSingletons(GameTestHelper h){h.assertValueEqual(AllPaletteBlocks.blocks().size(),35,"Only35 new windows/panes; framed glass has one existing owner");h.assertTrue(AllPaletteBlocks.FRAMED_GLASS==AllBlocks.FRAMED_GLASS&&PaletteStoneRegistry.blocks().size()==252,"Original root glass identity and stone owner registry survive");var seen=new HashSet<Block>();for(var set:List.of(AllBlocks.COPPER_SHINGLES,AllBlocks.COPPER_TILES)){h.assertValueEqual(set.blocks().size(),24,"Source24 copper states per set");for(var block:set.blocks())h.assertTrue(seen.add(block)&&block.asItem()!=Items.AIR&&BuiltInRegistries.BLOCK.getKey(block).getNamespace().equals(Create.ID),"One real native block/item per exact copper ID");}for(var block:AllPaletteBlocks.blocks().values())h.assertTrue(block.asItem()!=Items.AIR,"Every source window/pane owns actual item");h.succeed();}
 @GameTest(structure=STRUCTURE)public void originalTranslucentWindowAndConnectedPaneCullingUsesActualNativeStates(GameTestHelper h){var oak=AllPaletteBlocks.OAK_WINDOW.defaultBlockState();var birch=AllPaletteBlocks.BIRCH_WINDOW.defaultBlockState();var framed=AllBlocks.FRAMED_GLASS.defaultBlockState();h.assertTrue(oak.skipRendering(framed,Direction.NORTH)&&!oak.skipRendering(framed,Direction.UP)&&!birch.skipRendering(framed,Direction.NORTH)&&birch.skipRendering(birch,Direction.UP),"Pinned opaque horizontal family faces and translucent self-only culling");var pane=AllPaletteBlocks.OAK_WINDOW_PANE.defaultBlockState();h.assertTrue(pane.skipRendering(pane,Direction.UP)&&!pane.skipRendering(pane.setValue(BlockStateProperties.NORTH,true),Direction.UP),"Vertical pane culling requires exact same actual state");h.succeed();}
 @GameTest(structure=STRUCTURE)public void realNativePaneGeometryAndWaterloggingDifferFromFullWindowCollision(GameTestHelper h){h.setBlock(P,AllPaletteBlocks.OAK_WINDOW);var pos=h.absolutePos(P);h.assertTrue(Block.isShapeFullBlock(h.getBlockState(P).getCollisionShape(h.getLevel(),pos)),"Source full glass collision");var pane=AllPaletteBlocks.OAK_WINDOW_PANE.defaultBlockState();h.setBlock(P,pane);h.assertTrue(!Block.isShapeFullBlock(h.getBlockState(P).getCollisionShape(h.getLevel(),pos))&&pane.setValue(BlockStateProperties.WATERLOGGED,true).getFluidState().is(FluidTags.WATER),"Real native cross-collision/waterlogged pane, not relabelled cube");h.succeed();}
 @GameTest(structure=STRUCTURE)public void actualNativeWeatheringAndWaxMapsContainEverySourceTransitionAndPreserveShapeProperties(GameTestHelper h){for(var set:List.of(AllBlocks.COPPER_SHINGLES,AllBlocks.COPPER_TILES))for(var variant:set.getVariants())for(var age:WeatherState.values()){var raw=set.get(variant,age,false);var waxed=set.get(variant,age,true);h.assertTrue(raw instanceof WeatheringCopper&&!(waxed instanceof WeatheringCopper),"Native weathering behavior belongs only to unwaxed source states");h.assertTrue(HoneycombItem.WAXABLES.get().get(raw)==waxed&&HoneycombItem.WAX_OFF_BY_BLOCK.get().get(waxed)==raw,"Actual native forward/inverse honeycomb paths");if(age!=WeatherState.OXIDIZED)h.assertTrue(WeatheringCopper.getNext(raw).orElseThrow()==set.get(variant,WeatherState.values()[age.ordinal()+1],false),"All18 real source aging transitions");if(age!=WeatherState.UNAFFECTED)h.assertTrue(WeatheringCopper.getPrevious(raw).orElseThrow()==set.get(variant,WeatherState.values()[age.ordinal()-1],false),"Actual native axe deoxidizing inverse");var state=raw.defaultBlockState();if(state.hasProperty(BlockStateProperties.WATERLOGGED))state=state.setValue(BlockStateProperties.WATERLOGGED,true);var result=HoneycombItem.getWaxed(state).orElseThrow();h.assertTrue(result.is(waxed)&&(!state.hasProperty(BlockStateProperties.WATERLOGGED)||result.getValue(BlockStateProperties.WATERLOGGED)),"Native transform copies source geometry/fluid properties");}h.succeed();}
 @GameTest(structure=STRUCTURE)public void actualSurvivalHoneycombAndAxeUseDebitsRealStockAndPreservesNativeStairState(GameTestHelper h){var raw=AllBlocks.COPPER_SHINGLES.get(CopperBlockSet.StairVariant.INSTANCE,WeatherState.WEATHERED,false);var state=raw.defaultBlockState().setValue(StairBlock.FACING,Direction.WEST).setValue(StairBlock.HALF,Half.TOP);h.setBlock(P,state);try(var f=NativeSurvivalTestPlayer.join(h,Vec3.atBottomCenterOf(h.absolutePos(P.east(3))))){var p=f.player();var honey=new ItemStack(Items.HONEYCOMB,3);p.setItemInHand(InteractionHand.MAIN_HAND,honey);var at=h.absolutePos(P);var hit=new BlockHitResult(Vec3.atCenterOf(at),Direction.UP,at,false);h.assertTrue(honey.useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,hit)).consumesAction()&&honey.getCount()==2&&h.getBlockState(P).is(AllBlocks.COPPER_SHINGLES.get(CopperBlockSet.StairVariant.INSTANCE,WeatherState.WEATHERED,true)),"Real native honeycomb action consumes one finite item");var axe=new ItemStack(Items.IRON_AXE);p.setItemInHand(InteractionHand.MAIN_HAND,axe);h.assertTrue(axe.useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,hit)).consumesAction()&&h.getBlockState(P).is(raw),"Actual native axe removes source wax");h.assertTrue(axe.useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,hit)).consumesAction()&&h.getBlockState(P).is(AllBlocks.COPPER_SHINGLES.get(CopperBlockSet.StairVariant.INSTANCE,WeatherState.EXPOSED,false)),"Actual native axe removes one oxidation stage");h.assertTrue(h.getBlockState(P).getValue(StairBlock.FACING)==Direction.WEST&&h.getBlockState(P).getValue(StairBlock.HALF)==Half.TOP&&axe.getDamageValue()==2&&!p.hasInfiniteMaterials(),"Native use retains original stair geometry and pays real durability");}h.succeed();}
 @GameTest(structure=STRUCTURE)public void originalWindowAndPaneSilkLootUsesActualNativeEnchantment(GameTestHelper h){try(var f=NativeSurvivalTestPlayer.join(h,Vec3.atBottomCenterOf(h.absolutePos(P.east(3))))){var normal=new ItemStack(Items.IRON_PICKAXE);var silk=normal.copy();silk.enchant(h.getLevel().registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.SILK_TOUCH),1);for(var block:List.of(AllPaletteBlocks.OAK_WINDOW,AllPaletteBlocks.WEATHERED_IRON_WINDOW_PANE,AllPaletteBlocks.TILED_GLASS)){h.setBlock(P,block);var state=h.getBlockState(P);h.assertTrue(Block.getDrops(state,h.getLevel(),h.absolutePos(P),null,f.player(),normal).isEmpty(),"Source normal glass break pays nothing");var drops=Block.getDrops(state,h.getLevel(),h.absolutePos(P),null,f.player(),silk);h.assertTrue(drops.size()==1&&drops.getFirst().is(block.asItem())&&drops.getFirst().getCount()==1,"Real source silk condition pays the original singleton item");}}h.succeed();}
 @GameTest(structure=STRUCTURE)public void actualCopperDoubleSlabLootAndSourceStairBlastResistanceRemainNative(GameTestHelper h){var block=AllBlocks.COPPER_TILES.get(CopperBlockSet.SlabVariant.INSTANCE,WeatherState.OXIDIZED,true);var state=block.defaultBlockState().setValue(SlabBlock.TYPE,SlabType.DOUBLE);h.setBlock(P,state);try(var f=NativeSurvivalTestPlayer.join(h,Vec3.atBottomCenterOf(h.absolutePos(P.east(3))))){var drops=Block.getDrops(state,h.getLevel(),h.absolutePos(P),null,f.player(),new ItemStack(Items.IRON_PICKAXE));h.assertValueEqual(drops.stream().filter(x->x.is(block.asItem())).mapToInt(ItemStack::getCount).sum(),2,"Source double copper slab pays exactly two original slabs");}for(var set:List.of(AllBlocks.COPPER_SHINGLES,AllBlocks.COPPER_TILES))for(var age:WeatherState.values())for(boolean waxed:new boolean[]{false,true})h.assertValueEqual(set.get(CopperBlockSet.StairVariant.INSTANCE,age,waxed).getExplosionResistance(),Blocks.COPPER_BLOCK.weathering().unaffected().getExplosionResistance(),"Source copper stair resistance does not inherit AIR zero");h.succeed();}
 private static void craft(GameTestHelper h,String id,CraftingInput input,ItemLike expected,int count){var holder=h.getLevel().getServer().getRecipeManager().byKey(ResourceKey.create(Registries.RECIPE,Create.asResource(id))).orElseThrow();h.assertTrue(holder.value() instanceof CraftingRecipe,"Actual loaded native crafting recipe");var recipe=(CraftingRecipe)holder.value();h.assertTrue(recipe.matches(input,h.getLevel()),"Source ingredients match native recipe "+id);var result=recipe.assemble(input);h.assertTrue(result.is(expected.asItem())&&result.getCount()==count,"Exact source item/yield from native recipe "+id);}
 @GameTest(structure=STRUCTURE)public void loadedSourceWindowAndPaneRecipesRetainActualIngredientCountsAndYields(GameTestHelper h){craft(h,"oak_window",CraftingInput.of(3,2,List.of(ItemStack.EMPTY,new ItemStack(Items.OAK_PLANKS),ItemStack.EMPTY,new ItemStack(Items.OAK_PLANKS),new ItemStack(Items.GLASS),new ItemStack(Items.OAK_PLANKS))),AllPaletteBlocks.OAK_WINDOW,2);craft(h,"oak_window_pane",CraftingInput.of(3,2,java.util.stream.IntStream.range(0,6).mapToObj(i->new ItemStack(AllPaletteBlocks.OAK_WINDOW)).toList()),AllPaletteBlocks.OAK_WINDOW_PANE,16);h.succeed();}
 @GameTest(structure=STRUCTURE)public void sourceCopperWaxRecipeUsesOneActualUnwaxedBlockAndHoneycomb(GameTestHelper h){craft(h,"crafting/copper/waxed_copper_shingles_from_honeycomb",CraftingInput.of(2,1,List.of(new ItemStack(AllBlocks.COPPER_SHINGLES.getStandard()),new ItemStack(Items.HONEYCOMB))),AllBlocks.COPPER_SHINGLES.get(CopperBlockSet.BlockVariant.INSTANCE,WeatherState.UNAFFECTED,true),1);h.succeed();}
}
